package com.company.platform.aigateway.orchestration;import java.time.*;import java.util.*;import org.springframework.stereotype.Component;@Component public class ContextCache{private final Map<String,Entry> data=new HashMap<>();private record Entry(UUID tenant,Map<String,Object> value,Instant expires){}public void put(UUID tenant,String key,Map<String,Object>value,Duration ttl){data.put(tenant+":"+key,new Entry(tenant,Map.copyOf(value),Instant.now().plus(ttl)));}public Optional<Map<String,Object>> get(UUID tenant,String key){Entry e=data.get(tenant+":"+key);return e==null||e.expires().isBefore(Instant.now())?Optional.empty():Optional.of(e.value());}public void invalidate(UUID tenant,String key){data.remove(tenant+":"+key);}}
